```python
import json
from fractions import Fraction

animals = (
    "ant", "stork", "dragon", "fish", "mannikin", "liger", "mouse",
    "worm", "chihuahua", "crow", "wolf", "dalmatian", "goat",
    "walrus", "beetle", "cobra", "dinosaur", "llama", "husky"
)

def atom(predicate, *args):
    return predicate + "(" + ",".join(args) + ")"

def neg(literal):
    return literal[1:] if literal.startswith("!") else "!" + literal

facts = {
    atom("negotiates", "ant", "stork"),
    atom("photograph", "dragon", "fish"),
    atom("hides_cards", "mannikin", "liger"),
    atom("located", "mouse", "Nigeria"),
    atom("neglects", "worm", "chihuahua"),
    neg(atom("surrenders", "crow", "wolf")),
    neg(atom("trades_piece", "dalmatian", "stork")),
}

money = {"stork": Fraction(98)}
if "walrus" in money and money["stork"] > money["walrus"]:
    facts.add(atom("more_money", "stork", "walrus"))

rules = []

def rule(name, premises, conclusion):
    rules.append((name, frozenset(premises), conclusion))

rule("Geography", [atom("located", "mouse", "Nigeria")],
     atom("located", "mouse", "Africa"))

plant = atom("builds_plant", "stork", "goat")
shout = atom("shouts", "mouse", "beetle")

rule("Rule1", [
    atom("negotiates", "ant", "stork"),
    neg(atom("trades_piece", "dalmatian", "stork"))
], plant)

for animal in animals:
    rule("Rule2", [atom("builds_plant", animal, "goat")], neg(shout))

rule("Rule3", [atom("more_money", "stork", "walrus")], neg(plant))
rule("Rule4", [atom("located", "mouse", "Africa")],
     atom("smiles", "mouse", "cobra"))

for entity in animals:
    rule("Rule5", [
        atom("hugs", entity, "dinosaur"),
        atom("smiles", entity, "cobra")
    ], atom("shouts", entity, "beetle"))

rule("Rule6", [atom("has_instrument", "llama")],
     atom("calls", "llama", "husky"))
rule("Rule7", [atom("works_agriculture", "mouse")],
     neg(atom("smiles", "mouse", "cobra")))

for animal in animals:
    rule("Rule8", [atom("photograph", animal, "fish")],
         neg(atom("calls", "llama", "husky")))

preferred = {
    ("Rule3", "Rule1"),
    ("Rule5", "Rule2"),
    ("Rule6", "Rule8"),
    ("Rule7", "Rule4"),
}

known = set(facts)
seen = set()
settled = False

for _ in range(1000):
    signature = frozenset(known)
    if signature in seen:
        break
    seen.add(signature)

    applicable = [r for r in rules if r[1] <= known]
    undefeated = [
        r for r in applicable
        if not any(
            other[2] == neg(r[2]) and (other[0], r[0]) in preferred
            for other in applicable
        )
    ]
    updated = facts | {r[2] for r in undefeated}

    if updated == known:
        settled = True
        break
    known = updated

if not settled or (shout in known and neg(shout) in known):
    print("UNSUPPORTED")
else:
    answer = (
        "proved" if shout in known else
        "disproved" if neg(shout) in known else
        "unknown"
    )
    evidence = {
        "derived": {
            "stork_builds_plant": plant in known,
            "mouse_shouts": shout in known,
            "mouse_does_not_shout": neg(shout) in known,
        },
        "supporting_rules": sorted({
            r[0] for r in undefeated if r[2] == neg(shout)
        }),
        "Rule5_missing_premises": sorted(
            premise
            for name, premises, conclusion in rules
            if name == "Rule5" and conclusion == shout
            for premise in premises - known
        ),
        "Rule3_applicable": any(r[0] == "Rule3" for r in applicable),
    }
    print(json.dumps(
        {"final_answer": answer, "evidence": evidence},
        separators=(",", ":")
    ))
